using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Informs TDLib that speaking state of a participant of an active group call has changed. Returns identifier of the participant if it is found
    /// </summary>
    public Task<TdLib.TdApi.Objects.MessageSender> SetGroupCallParticipantIsSpeakingAsync(int groupCallId = default, int audioSource = default, bool isSpeaking = default)
    {

           using var activity =  StartCallActivity("SetGroupCallParticipantIsSpeakingAsync", typeof(SetGroupCallParticipantIsSpeaking).FullName ?? "SetGroupCallParticipantIsSpeakingAsync");

           try
           {
             return client.SetGroupCallParticipantIsSpeakingAsync(groupCallId, audioSource, isSpeaking);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
